{
  "report": "Resumo executivo — ALUP11 (até 2025-08-01): a leitura técnica mostra uma correção de curto/médio prazo: preço em 29,70 está abaixo das médias de curto/médio (MM20 29,87 e MM50 30,27) mas ainda acima da MM200 (28,99), o que deixa o contexto de longo prazo positivo enquanto o curto/médio prazo está enfraquecido. MACD negativo e histograma levemente negativo, RSI em ~47 e bandas de Bollinger próximas ao meio indicam momentum fraco e consolidação com viés de baixa. Grau de convicção do sinal de curto/médio prazo: moderado.",
  "signal": "Baixa",
  "support_levels": [
    29.18,
    28.99,
    28.63
  ],
  "resistance_levels": [
    29.87,
    30.27,
    31.30
  ],
  "indicator_readings": [
    {
      "indicator": "MM20",
      "reading": "29.8725",
      "interpretation": "Preço (29,70) abaixo da MM20 → pressão de curto prazo; MM20 vem recuando desde o fim de julho."
    },
    {
      "indicator": "MM50",
      "reading": "30.2680",
      "interpretation": "Preço abaixo da MM50 → enfraquecimento da tendência de médio prazo; resistência clara em ~30,27."
    },
    {
      "indicator": "MM200",
      "reading": "28.9902",
      "interpretation": "Preço acima da MM200 → tendência de longo prazo ainda positiva; MM200 atua como suporte structural (~28,99)."
    },
    {
      "indicator": "EMA9",
      "reading": "29.6280",
      "interpretation": "EMA9 abaixo da EMA21 e ligeiramente abaixo do preço → curto prazo ambíguo/leve suporte de curtíssimo prazo, mas frágil."
    },
    {
      "indicator": "EMA21",
      "reading": "29.8420",
      "interpretation": "EMA21 acima do preço → resistência de curtíssimo/médio prazo; EMA9 < EMA21 confirma viés baixista curto."
    },
    {
      "indicator": "MACD",
      "reading": "-0.2267",
      "interpretation": "MACD negativo e abaixo da linha de sinal → momentum vendedor moderado."
    },
    {
      "indicator": "MACD_signal",
      "reading": "-0.2184",
      "interpretation": "Linha de sinal negativa; cruzamento do MACD para baixo sinalizou perda de impulso em julho."
    },
    {
      "indicator": "MACD_hist",
      "reading": "-0.0083",
      "interpretation": "Histograma levemente negativo e próximo de zero → momentum fraco e possibilidade de estabilização/consolidação."
    },
    {
      "indicator": "BB_lower",
      "reading": "28.9726",
      "interpretation": "Banda inferior em ~28,97 → suporte técnico relevante antes da MM200; preço acima desta banda."
    },
    {
      "indicator": "BB_mid",
      "reading": "29.8725",
      "interpretation": "Meio das Bollinger = MM20 (29,87) atuando como resistência imediata."
    },
    {
      "indicator": "BB_upper",
      "reading": "30.7724",
      "interpretation": "Banda superior em ~30,77 → resistência de volatilidade; romper com volume confirmaria recuperação mais ampla."
    },
    {
      "indicator": "RSI14",
      "reading": "47.0519",
      "interpretation": "RSI neutro (~47) → sem condição de sobrecompra/sobrevenda; indica falta de força direcional."
    },
    {
      "indicator": "Volume",
      "reading": "2368221100",
      "interpretation": "Volume do pregão ~2,37e9. Há picos de volume no histórico que coincidiram com movimentos fortes; as quedas recentes não têm confirmação volumétrica consistente."
    }
  ]
}
